def cache_sim(capacity, ttl, ops):
    cache = {}  # key -> (value, write_time)
    lru_order = []  # list of keys in order of most recently used
    results = []

    def is_expired(key, current_time):
        if key not in cache:
            return True
        write_time = cache[key][1]
        return current_time >= write_time + ttl

    def mark_as_most_recent(key):
        if key in lru_order:
            lru_order.remove(key)
        lru_order.append(key)

    for op in ops:
        if op[0] == 'put':
            t, key, value = op[1], op[2], op[3]

            # Check if key exists and is not expired
            key_exists = key in cache and not is_expired(key, t)

            # If key is absent (doesn't exist or is expired) and cache is at capacity
            # we need to evict the least recently used entry
            if not key_exists and len([k for k in cache if not is_expired(k, t)]) >= capacity:
                # Find the least recently used non-expired key and evict it
                for k in lru_order:
                    if not is_expired(k, t):
                        del cache[k]
                        lru_order.remove(k)
                        break

            # Store the value
            cache[key] = (value, t)
            mark_as_most_recent(key)

        elif op[0] == 'get':
            t, key = op[1], op[2]

            if key in cache and not is_expired(key, t):
                value = cache[key][0]
                mark_as_most_recent(key)
                results.append(value)
            else:
                results.append(-1)

    return results

